<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoCentro, departamentosPorPais, distritosPorProvincia, guardarCentro, listarCentros, listarPaisesCentro, provinciasPorDepartamento } from '../services/centrosEnsenanza'
import type { CentroEnsenanza, CentroPayload, UbigeoOption } from '../interfaces/centrosEnsenanza.interface'
const rows=ref<CentroEnsenanza[]>([]),countries=ref<UbigeoOption[]>([]),departments=ref<UbigeoOption[]>([]),provinces=ref<UbigeoOption[]>([]),districts=ref<UbigeoOption[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),loadingUbigeo=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<CentroPayload>({codigo:'',nombre:'',pais_id:null,departamento_id:null,provincia_id:null,distrito_id:null})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const location=(item:CentroEnsenanza)=>[item.pais_nombre,item.departamento_nombre,item.provincia_nombre,item.distrito_nombre].filter(Boolean).join(' - ')||'Sin especificar'
const canDepartment=computed(()=>!!form.pais_id),canProvince=computed(()=>!!form.departamento_id),canDistrict=computed(()=>!!form.provincia_id)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarCentros(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
async function loadCountries(){if(countries.value.length)return;try{countries.value=await listarPaisesCentro()}catch(v){error.value=message(v)}}
async function selectCountry(keep?:number|null){departments.value=[];provinces.value=[];districts.value=[];if(!keep){form.departamento_id=null;form.provincia_id=null;form.distrito_id=null}if(!form.pais_id)return;loadingUbigeo.value=true;try{departments.value=await departamentosPorPais(form.pais_id)}catch(v){error.value=message(v)}finally{loadingUbigeo.value=false}}
async function selectDepartment(keep?:number|null){provinces.value=[];districts.value=[];if(!keep){form.provincia_id=null;form.distrito_id=null}if(!form.departamento_id)return;loadingUbigeo.value=true;try{provinces.value=await provinciasPorDepartamento(form.departamento_id)}catch(v){error.value=message(v)}finally{loadingUbigeo.value=false}}
async function selectProvince(keep?:number|null){districts.value=[];if(!keep)form.distrito_id=null;if(!form.provincia_id)return;loadingUbigeo.value=true;try{districts.value=await distritosPorProvincia(form.provincia_id)}catch(v){error.value=message(v)}finally{loadingUbigeo.value=false}}
async function open(item?:CentroEnsenanza){editing.value=item?.id??null;Object.assign(form,{codigo:item?.codigo??'',nombre:item?.nombre??'',pais_id:item?.pais_id??null,departamento_id:item?.departamento_id??null,provincia_id:item?.provincia_id??null,distrito_id:item?.distrito_id??null});error.value='';modal.value=true;await loadCountries();if(form.pais_id)await selectCountry(form.departamento_id);if(form.departamento_id)await selectDepartment(form.provincia_id);if(form.provincia_id)await selectProvince(form.distrito_id)}
async function save(){const codigo=form.codigo.trim().toUpperCase(),nombre=form.nombre.trim().toUpperCase();if(!codigo)return void(error.value='El código es obligatorio.');if(codigo.length>10)return void(error.value='El código admite como máximo 10 caracteres.');if(nombre.length<3)return void(error.value='El nombre debe tener al menos 3 caracteres.');saving.value=true;error.value='';try{await guardarCentro(editing.value,{...form,codigo,nombre});modal.value=false;success.value=`Centro de enseñanza ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:CentroEnsenanza){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} ${item.nombre}?`))return;try{const r=await cambiarEstadoCentro(item.id);item.estado=r.estado;success.value=r.message??`Centro ${item.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Centros de enseñanza</nav><header class="hero"><div class="mark">CE</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Centros de enseñanza</h1><p>Instituciones educativas y su ubicación geográfica para estudios y capacitaciones.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo centro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código o nombre<input v-model.trim="criterio" placeholder="Ej. UNMSM o UNIVERSIDAD"></label><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><header><div><small>MAESTRO DE FORMACIÓN</small><h2>Centros registrados</h2></div></header><div v-if="loading" class="empty">Consultando centros…</div><div v-else-if="!rows.length" class="empty">No se encontraron centros de enseñanza.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Código</th><th>Nombre</th><th>Ubicación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td>{{location(item)}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">CE</div><div><small>MAESTRO DE FORMACIÓN</small><h2>{{editing?'Editar':'Registrar'}} centro</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label class="wide">Nombre *<input v-model="form.nombre" maxlength="200" @input="form.nombre=form.nombre.toUpperCase()"></label><label>País<select v-model="form.pais_id" @change="selectCountry()"><option :value="null">Seleccione un país</option><option v-for="x in countries" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Departamento<select v-model="form.departamento_id" :disabled="!canDepartment||loadingUbigeo" @change="selectDepartment()"><option :value="null">Seleccione un departamento</option><option v-for="x in departments" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Provincia<select v-model="form.provincia_id" :disabled="!canProvince||loadingUbigeo" @change="selectProvince()"><option :value="null">Seleccione una provincia</option><option v-for="x in provinces" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Distrito<select v-model="form.distrito_id" :disabled="!canDistrict||loadingUbigeo"><option :value="null">Seleccione un distrito</option><option v-for="x in districts" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><p v-if="loadingUbigeo" class="loading">Cargando ubicación…</p><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff0f5;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(440px,100%);font-size:.52rem}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(760px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:10px;font-size:.5rem}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.loading{color:#89959a;font-size:.48rem}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
